using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.FibonacciAtomic.NativeContinuation.Acquisition;

internal sealed class NativeBinaryRowDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Binary computation of an original suffix row.", H("Binary original suffix row"),
        Blocks(
            Paragraph(Text("The row recurrence uses the original high-to-low native reader: the incoming guard is not (s=true and last b=true), and the successor seam is first b. Distinct allowed modes contribute separately even when they have the same successor.")),
            Paragraph(Text("A single fixed finite-control binary transducer reads the five explicit permission bits and any finite interleaved binary child row. It computes both original guarded sums exactly. Its carries are bounded by four; three extra columns discharge the carry without truncation.")),
            Paragraph(Text("The instruction proof counts the permission scan, every bit read and write, carry draining, control jumps and output reversal. The existing compiler then supplies actual input initialization, stack storage and access simulation, and physical single-tape output. The resulting bit-time bound is universal in the child width.")),
            Paragraph(Text("This transducer computes one backward row. Acquiring a whole suffix table while retaining its entries and reconstructing a successful original word requires a larger program, whose runtime is not part of the single-row statement.")),
            Describe.Lean(DescribeId.Create("native-binary-column"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.Column"), H("A pair of count bits"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Column is Bool times Bool: one bit for each original incoming seam."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-carry"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.Carry"), H("The two finite carries"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Carry is Fin 5 times Fin 5. Both carries belong to the finite program control and never store an unbounded integer."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-serialize"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.serialize"), H("Interleaved count representation"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every finite list xs of bit pairs, serialize xs writes the false-seam bit and then the true-seam bit at each column. Columns are little endian."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-parse"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.parse"), H("Decoding paired columns"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every bit list, parse groups successive bits into false-seam and true-seam columns. A final unmatched bit is ignored; the proved program output always has even length."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-value"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.value"), H("The represented child row"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every column list xs, value xs applies the existing little-endian bitsValue to its two projections. Leading high zero columns remain allowed."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-decode"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.decode"), H("Reading a serialized row"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every bit list bs, decode bs applies value to parse bs."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-input"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.input"), H("Explicit original restrictions"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every original allowed set a and finite child column list xs, input a xs contains five membership bits in the order zero, low, middle, high, ends, followed by serialize xs. No table, run certificate or resource evidence is part of the input."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-round"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.round"), H("One simultaneous binary column"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every original allowed set a, two carries below five and input column p, round forms each original guarded sum of selected p bits plus its carry. The parity bits are output and the two quotients by two become the next carries. A five-term sum plus a carry below five is below ten."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-drain"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.drain"), H("Draining the finite carries"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every natural n and pair of carries c, drain n c serializes their next n binary columns by repeatedly taking parity and dividing by two."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-columns"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.columns"), H("The binary row function"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every a, c and finite child row xs, columns a c xs scans round across all columns and then appends three drain columns. Three columns suffice for every carry below five, including zero."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-control"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.Control"), H("Finite control labels"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The labels store a parser position below six, an original five-mode permission subset, two carries below five, at most one bit pair and a drain position below four. No label contains an input-sized word or natural-number counter."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-scanprogram"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.scanProgram"), H("Primitive counted instructions"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("scanProgram uses only the supplied pop, push, goto and halt instructions on two Boolean stacks. It reads each of the five permission bits, scans both child bits, writes both result bits and drains the carries. An incomplete child pair or permission prefix fails."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-program"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.program"), H("Restoring output orientation"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("program sequences scanProgram with the existing two-stack transfer routine. This physical reversal restores the original interleaved little-endian column order."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-controlencoding"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.controlEncoding"), H("An explicit finite instruction table"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("controlEncoding enumerates all masks as sublists of the original five modes and all finite label fields. The computable list index and lookup form a finite Encoding; one additional unused index decodes to the failure label."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-encoding"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.encoding"), H("Composed finite labels"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("encoding combines controlEncoding with the existing four-label transfer encoding using the supplied sum encoding."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-stackmachine"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.stackMachine"), H("The compiled Boolean-stack graph"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("stackMachine is the existing StackProgram compilation of program and its finite encoding. Its instructions inspect or change one bit on one of two stacks."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-binarymachine"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.binaryMachine"), H("The physical binary transducer"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("binaryMachine is the supplied StackCompile compilation of stackMachine into the original single-tape machine, including input initialization and physical tape output."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-serialize-length"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.serialize_length"), H("Serialized row length"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every xs : List Column, (serialize xs).length = 2 * xs.length."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("native-binary-parse-serialize"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.parse_serialize"), H("Exact paired decoding"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every xs : List Column, parse (serialize xs) = xs."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("native-binary-columns-length"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.columns_length"), H("Output column width"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every a : Finset Window, c : Carry and xs : List Column, (columns a c xs).length = xs.length + 3."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("native-binary-registers"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.registers"), H("Two row registers"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For all src and dst : List Bool and j : Fin 2, registers src dst j is src when j = 0 and dst otherwise."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-insertbit"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.insertBit"), H("A permission bit"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every a : Finset Window, b : Window and v : Bool, insertBit a b v is insert b a when v is true and a otherwise."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-binary-exec-program"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.exec_program"), H("Exact instruction execution"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every a : Finset Window and xs : List Column, Exec program program.start (registers (input a xs) []) (8 * xs.length + 28) (true, registers (serialize (columns a (0,0) xs)) []). The complete original two-register execution is available for register-frame composition."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("native-binary-row"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeBinaryRow.native_binary_row"), H("Exact native row computation in quadratic bit time"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every a : Finset original Window and every xs : List (Bool times Bool), input a xs has length 5 + 2 * xs.length; serialize (columns a (0,0) xs) has length 2 * (xs.length+3); its decode equals advance a (value xs); and there exist time and tape such that time <= 16384 * (xs.length+1)^2, Complexity.runInput binaryMachine time (input a xs) = some (true,tape), and tape.output = serialize (columns a (0,0) xs).")), Paragraph(Text("Simultaneous carry induction proves that both output values equal the corresponding original five-mode sums. The counted stack execution uses exactly 8 * xs.length + 28 instructions, including parsing and final reversal. StackCompile.simulate is applied to that proved execution; expanding its initialization and simulation budgets gives the stated quadratic bound. Empty rows, empty and full allowed sets, zero child values, repeated successor seams and arbitrary high zero padding are all within the quantifiers."))), DescribeRole.Theorem)),
        [DocumentEdge.Dependency.Create(GidRef.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeSuffixAcquisition")),
         DocumentEdge.Dependency.Create(GidRef.Create("D5/S0/Computability/BinaryMachine/StackWords")),
         DocumentEdge.Dependency.Create(GidRef.Create("D5/S0/Computability/BinaryMachine/StackCompile")),
         DocumentEdge.Dependency.Create(GidRef.Create("D5/S0/Computability/PhysicalDivider/WordArithmetic"))]));
}
